Translate the following GNU C++17 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <iostream>
#include <queue>
#include <algorithm>
using namespace std;

const int MAXN = 25;
const int MAXE = 400005;
const int INF = 1000000007;
const int SOURCE = 501;
const int SINK = 502;

char firstGrid[MAXN][MAXN], secondGrid[MAXN][MAXN];
int distSafe[MAXN][MAXN];
int distBetween[MAXN][MAXN][MAXN][MAXN];
queue<pair<int, int>> q;
int dirX[4] = {-1, 1, 0, 0};
int dirY[4] = {0, 0, -1, 1};

struct FlowEdge { int u, v, fl, c, nxt; } edges[MAXE];
int edgeCnt = 0, head[505], parentEdge[505], used[505], depth[505];
int answer = 0;

inline void addEdge(int u, int v, int cap) {
    edges[++edgeCnt] = {u, v, 0, cap, head[u]};
    head[u] = edgeCnt;
    edges[++edgeCnt] = {v, u, 0, 0, head[v]};
    head[v] = edgeCnt;
}

inline bool findPath() {
    queue<int> qu;
    for (int i = 0; i <= SINK; i++) used[i] = depth[i] = 0;
    qu.push(SOURCE);
    used[SOURCE] = 1;
    depth[SOURCE] = 1;
    while (!qu.empty()) {
        int x = qu.front(); qu.pop();
        for (int i = head[x]; i; i = edges[i].nxt) {
            int y = edges[i].v;
            if (!used[y] && edges[i].fl < edges[i].c) {
                parentEdge[y] = i;
                used[y] = 1;
                depth[y] = depth[x] + 1;
                qu.push(y);
                if (y == SINK) return true;
            }
        }
    }
    return false;
}

inline int sendFlow(int x, int now) {
    if (x == SINK || !now) return now;
    int remain = now;
    for (int i = head[x]; i; i = edges[i].nxt) {
        if (edges[i].c > edges[i].fl && depth[edges[i].v] == depth[x] + 1) {
            int pushed = sendFlow(edges[i].v, min(remain, edges[i].c - edges[i].fl));
            if (!pushed) depth[edges[i].v] = 0;
            edges[i].fl += pushed;
            edges[((i - 1) ^ 1) + 1].fl -= pushed;
            remain -= pushed;
            if (remain == 0) break;
        }
    }
    return now - remain;
}

inline void runDinic() {
    while (findPath()) answer += sendFlow(SOURCE, INF);
}

int main() {
    int n, limit;
    cin >> n >> limit;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            distSafe[i][j] = 10000;
            cin >> firstGrid[i][j];
            if (firstGrid[i][j] == 'Z') {
                q.push({i, j});
                distSafe[i][j] = 0;
            }
            if (firstGrid[i][j] <= '9')
                addEdge(SOURCE, (i - 1) * n + j, firstGrid[i][j] - '0');
        }
    }
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int i = 0; i < 4; i++) {
            int nx = x + dirX[i], ny = y + dirY[i];
            if (nx > 0 && ny > 0 && nx <= n && ny <= n && firstGrid[nx][ny] <= '9' && distSafe[nx][ny] > distSafe[x][y] + 1) {
                distSafe[nx][ny] = distSafe[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (firstGrid[i][j] > '9') continue;
            for (int k = 1; k <= n; k++)
                for (int l = 1; l <= n; l++)
                    distBetween[i][j][k][l] = 10000;
            q.push({i, j});
            distBetween[i][j][i][j] = 0;
            while (!q.empty()) {
                int x = q.front().first, y = q.front().second;
                q.pop();
                for (int f = 0; f < 4; f++) {
                    int nx = x + dirX[f], ny = y + dirY[f];
                    if (nx > 0 && ny > 0 && nx <= n && ny <= n && firstGrid[nx][ny] <= '9' &&
                        distBetween[i][j][nx][ny] > distBetween[i][j][x][y] + 1 &&
                        distBetween[i][j][x][y] < distSafe[x][y]) {
                        distBetween[i][j][nx][ny] = distBetween[i][j][x][y] + 1;
                        q.push({nx, ny});
                    }
                }
            }
            for (int k = 1; k <= n; k++)
                for (int l = 1; l <= n; l++)
                    if (distBetween[i][j][k][l] <= min(distSafe[k][l], limit))
                        addEdge((i - 1) * n + j, (k - 1) * n + l + 100, 10000);
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            cin >> secondGrid[i][j];
            if (secondGrid[i][j] <= '9')
                addEdge((i - 1) * n + j + 100, SINK, secondGrid[i][j] - '0');
        }
    }
    runDinic();
    cout << answer;
    return 0;
}
